const fx=(v,d=3)=>v==null||v===''?'n/a':(typeof v=='number'?(Number.isInteger(v)?v:v.toFixed(d)):v);
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const P=DB.proj;
const BATCH=O(DB.batch),EXT=Object.fromEntries(O(DB.ext).map(r=>[r.Compound_ID,r.Actual_Target])),VS=O(DB.vs),CS=O(DB.cs),ADM=O(DB.admall),MCH=O(DB.mchall),SIM=O(DB.sim),SDF=DB.sdf;
const by=(a,k)=>{const m={};a.forEach(r=>(m[r[k]]=m[r[k]]||[]).push(r));return m};
const BSTD=by(BATCH,'Standardized_SMILES'),CSB=by(CS,'SMILES'),AMB=by(ADM,'SMILES'),MCB=by(MCH,'SMILES'),VSB=by(VS,'Standardized_SMILES');
const bd=(v,kind)=>{const s=String(v);let c='b-n';
 if(kind=='pf')c=/^(PASS|PASSED)/i.test(s)?'b-g':/WARN/i.test(s)?'b-a':/FAIL/i.test(s)?'b-r':'b-n';
 else if(kind=='risk')c=/low/i.test(s)?'b-g':/mod|med/i.test(s)?'b-a':/high/i.test(s)?'b-r':'b-n';
 else if(kind=='alert')c=(s=='false'||s=='0'||s=='None')?'b-g':'b-a';
 else if(kind=='ad')c=(s=='true'||s=='IN_DOMAIN'||s=='In-Domain'||s=='OK')?'b-g':(/OUT|HIGH_LEV/.test(s)?'b-a':(/REJ|INVALID/.test(s)?'b-r':'b-n'));
 else c='b-i';
 return `<span class="badge ${c}">${esc(v)}</span>`};
