function mkTable(host,o){const S={q:'',sk:null,sd:1,pg:0,hid:new Set(o.hide||[]),f:{},sel:null};const ps=o.ps||15;
 host.innerHTML=`<div class="row"><input type="search" placeholder="Search" aria-label="Search table" class="q">${(o.filters||[]).map(k=>`<select data-f="${k}" aria-label="Filter ${k}"><option value="">${k}: all</option>${[...new Set(o.rows.map(r=>r[k]))].map(v=>`<option>${esc(v)}</option>`).join('')}</select>`).join('')}<span class="sp"></span><small class="cnt"></small><div class="cols"><button class="btn cb">Columns</button><div>${o.cols.map(c=>`<label><input type="checkbox" data-c="${c.k}" ${S.hid.has(c.k)?'':'checked'}> ${esc(c.l)}</label>`).join('')}</div></div></div><div class="tw"><table><thead></thead><tbody></tbody></table></div><div class="pager"></div>`;
 const q=host.querySelector('.q');
 const data=()=>{let r=o.rows.filter(x=>Object.entries(S.f).every(([k,v])=>!v||String(x[k])==v)&&(!S.q||o.cols.some(c=>String(x[c.k]??'').toLowerCase().includes(S.q))));if(S.sk)r=[...r].sort((a,b)=>{const x=a[S.sk],y=b[S.sk];return (x==null)-(y==null)||(x>y?1:x<y?-1:0)*S.sd});return r};
 const draw=()=>{const cs=o.cols.filter(c=>!S.hid.has(c.k)),r=data(),np=Math.max(1,Math.ceil(r.length/ps));if(S.pg>=np)S.pg=np-1;
  host.querySelector('thead').innerHTML='<tr>'+cs.map(c=>`<th tabindex="0" data-k="${c.k}">${esc(c.l)}${S.sk==c.k?(S.sd>0?' &#9650;':' &#9660;'):''}</th>`).join('')+'</tr>';
  host.querySelector('tbody').innerHTML=r.slice(S.pg*ps,S.pg*ps+ps).map((x,i)=>`<tr data-i="${S.pg*ps+i}" class="${S.sel===x?'sel':''}">`+cs.map(c=>`<td class="${c.cls||(typeof x[c.k]=='number'?'n':'')}">${c.f?c.f(x[c.k],x):esc(typeof x[c.k]=='number'?fx(x[c.k],c.d??4):(x[c.k]??'n/a'))}</td>`).join('')+'</tr>').join('');
  host.querySelector('.cnt').textContent=r.length+' of '+o.rows.length+' rows';
  host.querySelector('.pager').innerHTML=`<button class="btn pv" ${S.pg?'':'disabled'}>Prev</button> Page ${S.pg+1} of ${np} <button class="btn nx" ${S.pg<np-1?'':'disabled'}>Next</button>`;
  host.querySelectorAll('th').forEach(h=>{const g=()=>{S.sd=S.sk==h.dataset.k?-S.sd:1;S.sk=h.dataset.k;draw()};h.onclick=g;h.onkeydown=e=>{if(e.key=='Enter')g()}});
  host.querySelectorAll('tbody tr').forEach(t=>t.onclick=()=>{S.sel=r[+t.dataset.i];draw();o.onRow&&o.onRow(S.sel)});
  host.querySelector('.pv').onclick=()=>{S.pg--;draw()};host.querySelector('.nx').onclick=()=>{S.pg++;draw()}};
 q.oninput=()=>{S.q=q.value.toLowerCase();S.pg=0;draw()};host.querySelectorAll('[data-f]').forEach(s=>s.onchange=()=>{S.f[s.dataset.f]=s.value;S.pg=0;draw()});
 host.querySelector('.cb').onclick=e=>e.target.closest('.cols').classList.toggle('o');host.querySelectorAll('[data-c]').forEach(c=>c.onchange=()=>{c.checked?S.hid.delete(c.dataset.c):S.hid.add(c.dataset.c);draw()});draw()}
