function tabs(host,list){host.innerHTML=`<div class="tabs">${list.map((t,i)=>`<button data-t="${i}">${t[0]}</button>`).join('')}</div><div class="tb"></div>`;const done={};const go=i=>{host.querySelectorAll('.tabs button').forEach((b,j)=>b.classList.toggle('on',i==j));const b=host.querySelector('.tb');b.innerHTML='';list[i][1](b);window.dispatchEvent(new Event('resize'))};host.querySelectorAll('.tabs button').forEach((b,i)=>b.onclick=()=>go(i));go(0)}
