function openMol(smi,extra){const mp=$('#mp');const cs=(CSB[smi]||[])[0],am=(AMB[smi]||[])[0],mc=(MCB[smi]||[])[0],bt=BSTD[smi]||[],vs=VSB[smi]||[],si=SDF.findIndex(m=>m.title==smi);
 const kv=o=>'<dl class="kv">'+Object.entries(o).filter(([k,v])=>v!=null).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${typeof v=='number'?fx(v,4):(v&&v.__h?v.__h:esc(v))}</dd>`).join('')+'</dl>';
 mp.innerHTML=`<button class="btn x" id="mx">Close</button><h3>Molecule details</h3><div id="mpm"></div><p class="mono" style="margin-top:8px;word-break:break-all">${esc(smi)}</p>`+(si>=0?`<p><button class="btn p" id="m3d">Open 3D view</button></p>`:'<p><small>No 3D structure for this molecule in the supplied SDF.</small></p>')+
 (cs?`<h4 style="margin-top:14px">Chemical space dataset</h4>`+kv({'Activity (pActivity)':cs.Activity,'Molecular weight':cs.MolWt,'QED':cs.qed,'LogP':cs.MolLogP,'TPSA':cs.TPSA,'H-bond donors':cs.NumHDonors,'H-bond acceptors':cs.NumHAcceptors,'Rotatable bonds':cs.NumRotatableBonds,'Applicability domain':cs.ad_status}):'')+
 (bt.length?`<h4 style="margin-top:14px">Batch prediction records (${bt.length})</h4>`+bt.slice(0,6).map(b=>kv({'Compound ID':b.Compound_ID,'Predicted value':b.Predicted_Value,'AD status':{__h:bd(b.AD_Status,'ad')},'Leverage h':b.Leverage_h,'Nearest similarity':b.Nearest_Similarity,'Warnings':b.Warning_Flags,'Actual target (external file)':EXT[b.Compound_ID]})).join('<hr style="border:0;border-top:1px solid var(--line)">')+(bt.length>6?`<small>and ${bt.length-6} more records</small>`:''):'')+
 (vs.length?`<h4 style="margin-top:14px">Virtual screening shortlist</h4>`+vs.map(v=>kv({'Rank':v.Rank,'Compound ID':v.Compound_ID,'Predicted value':v.Predicted_Value,'Screening':v.Screening_Reason})).join(''):'')+
 (am?`<h4 style="margin-top:14px">ADMET (modelling set)</h4>`+kv({'Formula':am.Formula,'MW':am['MW (g/mol)'],'LogP':am.LogP,'TPSA':am['TPSA (Å²)'],'ESOL class':am['ESOL Class'],'GI absorption':am['GI Absorption'],'BBB permeability':am['BBB Permeability'],'Safety risk':{__h:bd(am['Safety Risk Level'],'risk')}}):'')+
 (mc?`<h4 style="margin-top:14px">Medicinal chemistry</h4>`+kv({'Status':{__h:bd(mc['MedChem Status'],'pf')},'Lipinski':{__h:bd(mc.Lipinski,'pf')},'QED':mc.QED,'QED category':mc['QED Category'],'SA score':mc['SA Score'],'SA category':mc['SA Category']}):'')+
 '<p style="margin-top:14px"><small>Only information present in the supplied files is shown. Missing sections mean this molecule does not appear in that file.</small></p>';
 drawMol($('#mpm'),smi,380,220);mp.classList.add('o');$('#mx').onclick=()=>mp.classList.remove('o');
 const b=$('#m3d');if(b)b.onclick=()=>{mp.classList.remove('o');show('cadd');cadd.focus(si)}}
