const R={},PAGES=[['overview','Overview'],['dataset','Dataset & QC'],['qsar','QSAR Results'],['space','Chemical Space'],['similarity','Chemical Similarity'],['readacross','Read-Across'],['admet','ADMET Profiling'],['medchem','Medicinal Chemistry'],['sar','SAR Analysis'],['batch','Batch Prediction'],['vs','Virtual Screening'],['external','External Validation'],['cadd','CADD / 3D Structures'],['summary','Final Summary']];
$('#side').innerHTML=`<div class="brand" style="display:flex;align-items:center;gap:10px"><img src="assets/img/logo-96.png" alt="BTGenZ logo" width="38" height="38" style="border-radius:9px"><span style="color:inherit">BTGen<span>Z</span></span></div><div class="tag">Computational Drug Discovery</div><div class="tgt"><b>Analysis</b><div>${esc(P.name)} (${esc(P.pid)})</div><b>Target protein</b><div>${esc(P.target)}</div><b>ChEMBL target ID</b><div>${esc(P.chembl)}</div><b>Activity endpoint</b><div>${esc(P.endpoint)}</div><b>Dataset</b><div>${esc(P.dataset)}</div></div>`+PAGES.map((p,i)=>`<a class="nv" href="#${p[0]}" data-p="${p[0]}"><i>${String(i+1).padStart(2,'0')}</i>${p[1]}</a>`).join('');
$('#topr').innerHTML=`<b>${esc(P.target.replace(/ \(BRAF\)/,''))}</b><br>${esc(P.dataset.replace('.xlsx',''))} &middot; Generated from the ${esc(P.gen.slice(0,10))} analysis run`;
