 PL('clp',[{type:'scatter',mode:'markers',x:cl.map(r=>r.tanimoto_similarity),y:cl.map(r=>r.abs_delta_activity),marker:{size:10,color:cl.map(r=>r.is_activity_cliff?'#f2b84b':'#35c2ff')},text:cl.map(r=>r.smiles_1+' / '+r.smiles_2),hovertemplate:'%{text}<br>Similarity %{x}<br>|Delta| %{y}<extra></extra>'}],{xaxis:{title:'Tanimoto similarity',gridcolor:'#ffffff12'},yaxis:{title:'Absolute activity difference',gridcolor:'#ffffff12'}});
