<div class="card"><div class="cadd-toolbar" id="caddNav"><div class="group"><span class="label">Structure</span><button class="btn on" data-tab="complex">BRAF Complex</button><button class="btn" data-tab="ligand">QSAR Ligands</button></div><div class="group"><span class="label">Layers</span><button class="btn on" id="vProtein">Protein</button><button class="btn on" id="vPose">Reference Pose</button><button class="btn" id="vPocket">Pocket</button></div><div class="group"><span class="label">Interactions</span><button class="btn" id="vHB">H-Bonds</button><button class="btn" id="vHyd">Hydrophobic</button><button class="btn" id="vIon">Ionic</button><button class="btn" id="vPi">π</button><button class="btn" id="vRes">Residues</button></div><div class="group"><span class="label">View</span><button class="btn on" id="vCartoon">Cartoon</button><button class="btn" id="vSurface">Surface</button><button class="btn" id="vSticks">Sticks</button><button class="btn" id="vReset">Reset</button><button class="btn" id="vSpin">Spin</button></div></div></div>
